 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = grid[0][0]
    marks = sorted({v for row in grid for v in row if v != bg})
    # The line color is the remaining third color, as shown in the demonstrations.
    for color in marks:
        pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == color]
        for r in range(h):
            cs = sorted(c for rr,c in pts if rr == r)
            for a,b in zip(cs, cs[1:]):
                for c in range(a+1,b):
                    if grid[r][c] == bg: out[r][c] = 3
        for c in range(w):
            rs = sorted(r for r,cc in pts if cc == c)
            for a,b in zip(rs, rs[1:]):
                for r in range(a+1,b):
                    if grid[r][c] == bg: out[r][c] = 3
    return out
